/// <summary>
///     extension of class <c>SalesTableType_ReturnItem</c>
/// </summary>
[ExtensionOf(classStr(SalesTableType_ReturnItem))]
final class AVASalesTableType_ReturnItemCls_Extension
{
    public boolean              clsReturnItemNumAsSalesIdSet;
    public SalesReturnItemNum   clsSeqNumSalesReturnItemNum;
    public SalesId              clsSeqNumSalesId;

}

Method.Source:
/// <summary>
///     AVA <c>formMethodDataSourceCreate</c> method.
/// </summary>
/// <param name="_element">
///     <c>FormRun</c> as type
/// </param>
/// <param name="_salestable_ds">
///     <c>FormDataSource</c> as type
/// </param>
public void formMethodDataSourceCreate(FormRun _element, FormDataSource _salestable_ds)
{
    //this.avaSetGlobalsToActualValues();

    next formMethodDataSourceCreate(_element, _salestable_ds);

    this.avaSetGlobalsToActualValues();


        // take over SalesId with first ReturnItemNum as same ReturnItemNum and release needless second ReturnItemNum
    salesTable.SalesId = salesTable.ReturnItemNum;
    NumberSeq::releaseNumber(SalesParameters::numRefSalesId().NumberSequenceId, clsSeqNumSalesReturnItemNum);

}

/// <summary>
///     AVA <c>avaSetGlobalsToActualValues</c> method.
/// </summary>
public void avaSetGlobalsToActualValues()
{
    clsSeqNumSalesReturnItemNum = salesTable.returnItemNum;
    clsSeqNumSalesId            = salesTable.SalesId;
}

 /// <summary>
 ///     AVA <c>formMethodDataSourceValidateWrite</c> method.
 /// </summary>
 /// <param name="_element">
 ///     <c>FormRun</c> as type
 /// </param>
 /// <param name="_salestable_ds">
 ///     <c>FormDataSource</c> as type
 /// </param>
 /// <returns>
 ///     <c>boolean</c> as return value
 /// </returns>
public boolean formMethodDataSourceValidateWrite(FormRun _element, FormDataSource _salestable_ds)
 {
     boolean ret;

     salesTable.SalesId = clsSeqNumSalesId;
     ret = next formMethodDataSourceValidateWrite(_element,_salestable_ds);
     salesTable.SalesId = salesTable.ReturnItemNum;
     return ret;
 }

/// <summary>
///     AVA <c>initValue</c> method.
///     AVA - Schneider 12.03.2024
/// </summary>
public void  initValue()
{
    next initValue();

    if (salesTable.returnItem())
    {
        salesTable.avaInitFromAVASalesParameters_ReturnItem();
    }
}

 /// <summary>
 ///     AVA <c>modifiedField</c> method.
 ///     AVA - Schneider 12.03.2024
 /// </summary>
 /// <param name="_fieldId">
 ///     <c>FieldId</c> as type
 /// </param>
 /// <param name="_tableId">
 ///     <c>TableId</c> as type
 /// </param>
 /// <param name="_uiEnabled">
 ///     <c>boolean</c> as type
 /// </param>
public void modifiedField(   FieldId _fieldId,
                             TableId _tableId,
                             boolean _uiEnabled  )
 {
     next modifiedField( _fieldId,
                         _tableId,
                         _uiEnabled  );

     if (_tableId == tableNum(SalesTable))
     {
         switch (_fieldId)
         {
             case fieldNum(SalesTable, CustAccount):
                 salesTable.avaInitCustAccountChanged_ReturnItem();
                 break;
         }
     }
 }

/// <summary>
///     AVA <c>formMethodDataSourceWrite</c> method.
///     AVA - Schneider 13.03.2024
/// </summary>
/// <param name="_element">
///     <c>FormRun</c> as type
/// </param>
/// <param name="_salestable_ds">
///     <c>FormDataSource</c> as type
/// </param>
public void formMethodDataSourceWrite(FormRun _element, FormDataSource _salestable_ds)
{
    next formMethodDataSourceWrite(_element, _salestable_ds);

    salesTable.avaInitFreightSettings_ReturnItem();
}
